"""1283 (#11): Record-Coverage-v1267.ps1 with a 'fall' case for the long fall loop and the landing (sweep 1260: no recording
had a long or hard fall). The source is teleported -FallHeight metres (default 6) above its usual spot (-35,-153) and falls
to the floor while the peer films from (-29,-146) at a level pitch (0) so the drop stays in frame. Pass (runtime): the
source fell at least 3 m, partner presentation stayed live and the partner showed a non-grounded traversal state."""
from pathlib import Path
N = Path(__file__).resolve().parent
src = (N / 'Record-Coverage-v1267.ps1').read_bytes().decode('utf-8')
crlf = '\r\n' in src
s = src.replace('\r\n', '\n')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:90])
    s = s.replace(old, new)
rep("param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='coverage-v1267a',[string]$Candidate='candidate-npc-combat-v1214l',[string[]]$Sources=@('client','host'),[string[]]$Cases=@('run8','slide'))",
    "param([ValidatePattern('^[a-z0-9-]+$')][string]$Take='coverage-v1283a',[string]$Candidate='candidate-npc-combat-v1214ak',[string[]]$Sources=@('client','host'),[string[]]$Cases=@('fall'),[double]$FallHeight=6)\n"
    "# 1283 (#11): 'fall' - the source drops -FallHeight m onto the floor while the peer films level. Generated by make_coverage_v1283.py.")
rep("""   & "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $peer -Pitch 8 -Quick|Out-Null""",
    """   & "$PSScriptRoot/Set-ObserverPitch.ps1" -Role $peer -Pitch $(if($case-eq'fall'){0}else{8}) -Quick|Out-Null""")
rep("""    if($case-eq'slide'-and$step-eq0-and$t-ge1000){""",
    """    if($case-eq'fall'-and$step-eq0-and$t-ge1000){C $source ('setviewpos -35 -153 {0} 0 0' -f (68.1+$FallHeight).ToString('F2',[Globalization.CultureInfo]::InvariantCulture));$step=1}
    if($case-eq'slide'-and$step-eq0-and$t-ge1000){""")
rep("""$samples.Add([pscustomobject]@{ms=$t;stance=$player.stance;active=@($player.active|ForEach-Object {$_.id});position=$player.position;remoteState=$ss.remoteState;weight=$mv.weight;slideState=$mv.slideState;slideWeight=$mv.slideWeight;active2=$mv.active})""",
    """$samples.Add([pscustomobject]@{ms=$t;stance=$player.stance;active=@($player.active|ForEach-Object {$_.id});position=$player.position;remoteState=$ss.remoteState;weight=$mv.weight;slideState=$mv.slideState;slideWeight=$mv.slideWeight;active2=$mv.active;traversal=$mv.traversalState;traversalWeight=$mv.traversalWeight;airborne=$mv.airborne})""")
rep("""   if($case-eq'slide'){if(!@($samples|Where-Object {$_.slideWeight-gt.8}).Count){throw 'Partner slide not presented'};$row.checks.Add('Partner slide presented')}""",
    """   if($case-eq'slide'){if(!@($samples|Where-Object {$_.slideWeight-gt.8}).Count){throw 'Partner slide not presented'};$row.checks.Add('Partner slide presented')}
   if($case-eq'fall'){$zs=@($samples|Where-Object {$_.position}|ForEach-Object {[double]$_.position[2]});$row.fallMetres=[Math]::Round((($zs|Measure-Object -Maximum).Maximum)-$zs[-1],2)
    if($row.fallMetres-lt3){throw "Source fell only $($row.fallMetres) m"};$row.checks.Add("Source fell $($row.fallMetres) m")}""")
out = s.replace('\n', '\r\n') if crlf else s
(N / 'Record-Coverage-v1283.ps1').write_bytes(out.encode('utf-8'))
print('ok')
